public static decimal CalculatePurchaseTotal(decimal carPrice, decimal clothingPrice, decimal bookPrice)
{
    // Check if the car price is at least double the combined price of the clothes and the book
    if (carPrice < (clothingPrice + bookPrice) * 2)
    {
        // If not, adjust the car price so it meets the constraint
        decimal newCarPrice;
        do
        {
            Console.WriteLine("Please enter a new car price that is at least double the combined price of the clothes and the book:");
            string input = Console.ReadLine();
            newCarPrice = Convert.ToDecimal(input);
        }
        while (newCarPrice < (clothingPrice + bookPrice) * 2);

        // Set the adjusted car price
        carPrice = newCarPrice;
    }

    // Calculate the total cost of the purchase
    decimal totalPrice = carPrice + clothingPrice + bookPrice;

    return totalPrice;
}
```
